-- The lake tables of the telemetry catalogue, contract 2.
CREATE TABLE IF NOT EXISTS item_created (event_version UTINYINT NOT NULL, producer_id UINTEGER NOT NULL, boot_id BIGINT NOT NULL, batch_seq BIGINT NOT NULL, row_no USMALLINT NOT NULL, timestamp_ns BIGINT NOT NULL, player_id UINTEGER NOT NULL, item_instance_id UBIGINT, grant_kind UTINYINT, item_id UINTEGER, quantity UINTEGER, via_mail UTINYINT, fact_id UBIGINT);
CREATE TABLE IF NOT EXISTS item_consumed (event_version UTINYINT NOT NULL, producer_id UINTEGER NOT NULL, boot_id BIGINT NOT NULL, batch_seq BIGINT NOT NULL, row_no USMALLINT NOT NULL, timestamp_ns BIGINT NOT NULL, player_id UINTEGER NOT NULL, item_instance_id UBIGINT, item_id UINTEGER);
CREATE TABLE IF NOT EXISTS penya_drops (event_version UTINYINT NOT NULL, producer_id UINTEGER NOT NULL, boot_id BIGINT NOT NULL, batch_seq BIGINT NOT NULL, row_no USMALLINT NOT NULL, timestamp_ns BIGINT NOT NULL, player_id UINTEGER NOT NULL, amount BIGINT, mob_index UINTEGER);
CREATE TABLE IF NOT EXISTS trade_penya (event_version UTINYINT NOT NULL, producer_id UINTEGER NOT NULL, boot_id BIGINT NOT NULL, batch_seq BIGINT NOT NULL, row_no USMALLINT NOT NULL, timestamp_ns BIGINT NOT NULL, player_id UINTEGER NOT NULL, trade_id UBIGINT, giver_player_id UINTEGER, receiver_player_id UINTEGER, amount BIGINT);
CREATE TABLE IF NOT EXISTS server_lifecycle (event_version UTINYINT NOT NULL, producer_id UINTEGER NOT NULL, boot_id BIGINT NOT NULL, batch_seq BIGINT NOT NULL, row_no USMALLINT NOT NULL, timestamp_ns BIGINT NOT NULL, player_id UINTEGER NOT NULL, kind UTINYINT);
CREATE TABLE IF NOT EXISTS farm_events (event_version UTINYINT NOT NULL, producer_id UINTEGER NOT NULL, boot_id BIGINT NOT NULL, batch_seq BIGINT NOT NULL, row_no USMALLINT NOT NULL, timestamp_ns BIGINT NOT NULL, player_id UINTEGER NOT NULL, kind UTINYINT, slot_index UINTEGER, type_id UINTEGER, item_count UINTEGER, target_player_id UINTEGER, fact_id UBIGINT, cost BIGINT);
CREATE TABLE IF NOT EXISTS sovereign_events (event_version UTINYINT NOT NULL, producer_id UINTEGER NOT NULL, boot_id BIGINT NOT NULL, batch_seq BIGINT NOT NULL, row_no USMALLINT NOT NULL, timestamp_ns BIGINT NOT NULL, player_id UINTEGER NOT NULL, kind UTINYINT, role UTINYINT, doctrine UTINYINT, power UTINYINT, task_id UINTEGER, used UINTEGER, max UINTEGER, gold BIGINT, item_count UINTEGER);
